document.querySelector('.menu-toggle').addEventListener('click',function(){const open=this.getAttribute('aria-expanded')!=='true';this.setAttribute('aria-expanded',open);document.querySelector('#navigation').classList.toggle('open',open)});
document.querySelectorAll('#navigation a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#navigation').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}));
const {groups,features,additional,doctors}=window.breorisData;
const q=s=>document.querySelector(s);
const arrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" stroke-width="1.4"/></svg>';
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function animateView(el){el.classList.remove('view-enter');requestAnimationFrame(()=>el.classList.add('view-enter'));}
function wireTabs(container,change){const buttons=[...container.querySelectorAll('[role=tab]')];buttons.forEach((b,i)=>{b.addEventListener('click',()=>change(i));b.addEventListener('keydown',e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%buttons.length;else if(e.key==='ArrowLeft')next=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=buttons.length-1;else return;e.preventDefault();change(next);buttons[next].focus()})})}
const groupNames=Object.keys(groups);
q('#service-tabs').innerHTML=groupNames.map((name,i)=>`<button type="button" id="service-tab-${i}" role="tab" aria-controls="service-list" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${name}</button>`).join('');
function showServices(index){q('#service-tabs').querySelectorAll('button').forEach((b,i)=>{b.setAttribute('aria-selected',i===index);b.tabIndex=i===index?0:-1});q('#service-list').setAttribute('aria-labelledby','service-tab-'+index);q('#service-list').innerHTML=groups[groupNames[index]].map(s=>`<button class="service-item" data-service="${escapeHTML(s)}"><span class="service-item-copy"><span>${s}</span><small class="service-price">${escapeHTML(window.BreorisPricing.summary(s))}</small></span>${arrow}</button>`).join('');animateView(q('#service-list'))}
wireTabs(q('#service-tabs'),showServices);showServices(0);
q('#feature-tabs').innerHTML=features.map((f,i)=>`<button type="button" id="feature-tab-${i}" role="tab" aria-controls="feature-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${f.tab}</button>`).join('');
function showFeature(index){const f=features[index];q('#feature-tabs').querySelectorAll('button').forEach((b,i)=>{b.setAttribute('aria-selected',i===index);b.tabIndex=i===index?0:-1});q('#feature-panel').setAttribute('aria-labelledby','feature-tab-'+index);q('#feature-title').textContent=f.title;q('#feature-text').innerHTML=f.text.map(p=>`<p>${escapeHTML(p)}</p>`).join('');q('#feature-image').src='assets/'+f.image;q('#feature-image').style.objectPosition=f.position||'center';q('#feature-image').setAttribute('data-i18n-original-alt',f.alt);q('#feature-image').alt=f.alt;q('#feature-book').dataset.service=f.service;window.BreorisLocale?.translateTree(q('#feature-panel'));animateView(q('.feature-copy'))}
wireTabs(q('#feature-tabs'),showFeature);showFeature(0);
q('#additional-list').innerHTML=additional.map(a=>`<details><summary>${a.title}</summary><p>${escapeHTML(a.text)}</p><button class="text-link" data-service="${escapeHTML(a.service)}">Записатися <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg></span></button></details>`).join('');
const doctorServices=[...new Set(doctors.flatMap(d=>d.services))];
q('#doctor-filter').insertAdjacentHTML('beforeend',doctorServices.map(s=>`<option value="${escapeHTML(s)}">${s}</option>`).join(''));
let showAll=false;
function renderDoctors(){const filter=q('#doctor-filter').value;const selected=doctors.filter(d=>filter==='all'||d.services.includes(filter));const visible=showAll?selected:selected.slice(0,6);q('#doctor-grid').innerHTML=visible.map(d=>`<article class="doctor-card"><${window.BreorisDoctorRoutes?.[d.id]?'a':'button'} class="doctor-photo" ${window.BreorisDoctorRoutes?.[d.id]?`href="${window.BreorisDoctorRoutes[d.id]}"`:`data-profile="${d.id}"`} aria-label="Про лікаря: ${d.name}"><img src="assets/${d.image}" alt="${d.name}" width="540" height="960" loading="lazy"><span class="profile-arrow" aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg></span></${window.BreorisDoctorRoutes?.[d.id]?'a':'button'}><h3>${d.short}</h3><p class="role">${d.role}</p><button class="text-link" data-doctor="${d.id}">Записатися <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg></span></button></article>`).join('');q('#doctor-count').textContent=`Показано ${visible.length} з ${selected.length} спеціалістів`;q('#show-doctors').hidden=selected.length<=6;q('#show-doctors').innerHTML=showAll?'Показати менше <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20V4M5 11l7-7 7 7"/></svg></span>':'Показати всіх лікарів <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 4v16M5 13l7 7 7-7"/></svg></span>';}
q('#doctor-filter').addEventListener('change',()=>{showAll=false;renderDoctors()});q('#show-doctors').addEventListener('click',()=>{showAll=!showAll;renderDoctors();if(!showAll)q('#likari').scrollIntoView({behavior:'smooth'})});renderDoctors();
function showProfile(id){const d=doctors.find(d=>d.id===id);if(!d)return;q('#profile-content').innerHTML=`<div class="profile-layout"><div class="profile-picture"><img src="assets/${d.image}" alt="${d.name}" width="540" height="960" loading="lazy"></div><div class="profile-info"><h2 id="profile-name">${d.name}</h2><ul>${d.credentials.map(c=>`<li>${c}</li>`).join('')}</ul><h3>Спеціалізується на</h3><ul>${d.specialties.map(c=>`<li>${c}</li>`).join('')}</ul>${d.note?`<p>${d.note}</p>`:''}<button class="button primary" data-doctor="${d.id}">Записатися <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg></span></button><a class="profile-original" href="assets/${d.image}" target="_blank" rel="noopener">Переглянути оригінальну картку</a></div></div>`;q('#profile-dialog').showModal()}
document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){q('#'+close.dataset.close).close();return}const profile=e.target.closest('[data-profile]');if(profile){showProfile(profile.dataset.profile);return}const doctor=e.target.closest('[data-doctor]');if(doctor){openBooking(null,doctor.dataset.doctor);return}const service=e.target.closest('[data-service]');if(service){openBooking(service.dataset.service);return}if(e.target.closest('[data-book]'))openBooking()});
document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}})});
const bookServices=Object.values(groups).flat();q('#book-service').innerHTML='<option value="any">Потрібна допомога з вибором</option>'+groupNames.map(g=>`<optgroup label="${g}">${groups[g].map(s=>`<option value="${escapeHTML(s)}">${s}</option>`).join('')}</optgroup>`).join('');
const pricing=window.BreorisPricing;
function updatePriceOptions(){
 const service=q('#book-service').value,rows=pricing.details[service];
 q('#book-detail-wrap').hidden=!rows;
 if(rows)q('#book-detail').innerHTML=(rows[0][0]==='consult'?'':'<option value="">Оберіть дослідження або процедуру</option>')+rows.map(([id,label])=>`<option value="${id}">${label}</option>`).join('');
 else q('#book-detail').replaceChildren();
 q('#book-repeat').value='first';updatePrice();
}
function updatePrice(){
 const service=q('#book-service').value,consultation=pricing.consultation.has(service)&&(!pricing.details[service]||q('#book-detail').value==='consult');
 q('#book-repeat-wrap').hidden=!consultation;if(!consultation)q('#book-repeat').value='first';
 const quote=pricing.quote(service,q('#book-detail').value,q('#book-doctor').value,q('#book-repeat').value==='repeat');
 q('#book-price').textContent=quote.label;
 q('#book-price-note').textContent=quote.note||'Точну суму підтвердить клініка перед візитом.';
 return quote;
}
q('#book-detail').addEventListener('change',updatePrice);
q('#book-repeat').addEventListener('change',updatePrice);
const times=['09:00','10:00','11:00','12:00','14:00','15:00','16:00','17:00'];let step=0,selectedTime='10:00';
function updateDoctors(preselected){const list=doctors.filter(d=>d.services.includes(q('#book-service').value));q('#book-doctor').innerHTML='<option value="any">Допоможіть обрати спеціаліста</option>'+list.map(d=>`<option value="${d.id}">${d.name}</option>`).join('');if(preselected&&list.some(d=>d.id===preselected))q('#book-doctor').value=preselected;updateDoctorPreview();updatePrice()}
function updateDoctorPreview(){const d=doctors.find(d=>d.id===q('#book-doctor').value);q('#booking-doctor-preview').innerHTML=d?`<div class="booking-preview"><img src="assets/${d.image}" alt="" width="64" height="70"><div><strong>${d.name}</strong><p>${d.role}</p></div></div>`:'<div class="booking-preview"><p>Адміністратор допоможе обрати фахівця для вашого звернення.</p></div>'}
q('#book-service').addEventListener('change',()=>{updatePriceOptions();updateDoctors()});q('#book-doctor').addEventListener('change',()=>{updateDoctorPreview();updatePrice()});
q('.time-options').innerHTML=times.map(t=>`<button type="button" data-time="${t}" aria-pressed="${t===selectedTime}">${t}</button>`).join('');q('.time-options').addEventListener('click',e=>{const b=e.target.closest('[data-time]');if(!b)return;selectedTime=b.dataset.time;q('.time-options').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b))});
function todayString(){const now=new Date();return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv'}).format(now)}
function openBooking(service,doctorId){if(window.BreorisBooking){window.BreorisBooking.open(service,doctorId);return}if(q('#profile-dialog').open)q('#profile-dialog').close();q('#booking-form').reset();step=0;selectedTime='10:00';q('.time-options').querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.time===selectedTime));if(doctorId){const d=doctors.find(d=>d.id===doctorId);q('#book-service').value=d.services[0]}else q('#book-service').value=service&&bookServices.includes(service)?service:'any';updatePriceOptions();updateDoctors(doctorId);q('#book-date').min=todayString();q('#book-date').value=todayString();q('#booking-form').hidden=false;q('#booking-success').hidden=true;q('.booking-steps').hidden=false;q('#booking-title').hidden=false;q('.demo-note').hidden=false;updateChannel();renderBooking();q('#booking-dialog').showModal()}
function doctorLabel(){const d=doctors.find(d=>d.id===q('#book-doctor').value);return d?d.short:'Спеціаліста підбере адміністратор'}
function dateLabel(){const value=q('#book-date').value;const locale={uk:'uk-UA',ru:'ru-RU',en:'en-GB'}[window.BreorisLocale?.language||'uk'];return value?new Intl.DateTimeFormat(locale,{day:'numeric',month:'long'}).format(new Date(value+'T12:00:00')):''}
function renderBooking(){document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=Number(p.dataset.panel)!==step);document.querySelectorAll('[data-step]').forEach(s=>{if(Number(s.dataset.step)===step)s.setAttribute('aria-current','step');else s.removeAttribute('aria-current')});q('#booking-title').textContent=['Оберіть послугу та лікаря','Коли вам зручно?','Як з вами зв’язатися?'][step];q('#book-back').hidden=step===0;q('#book-next').innerHTML=['Обрати час <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16M13 5l7 7-7 7"/></svg></span>','Залишити контакти <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16M13 5l7 7-7 7"/></svg></span>','Переглянути заявку <span aria-hidden="true"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 12h16M13 5l7 7-7 7"/></svg></span>'][step];q('#booking-error').hidden=true;const serviceLabel=q('#book-service').selectedOptions[0].textContent;q('#time-summary').textContent=serviceLabel+' · '+doctorLabel();q('#contact-summary').textContent=serviceLabel+' · '+doctorLabel()+' · '+dateLabel()+', '+selectedTime+' · '+updatePrice().label;animateView(document.querySelector(`[data-panel="${step}"]`));q('#booking-dialog').scrollTop=0}
q('#book-back').addEventListener('click',()=>{step=Math.max(0,step-1);renderBooking()});
function updateChannel(){const channel=q('input[name=channel]:checked').value;q('#telegram-field').hidden=channel!=='Telegram';q('#contact-hint').textContent=channel==='Дзвінок'?'У робочій версії адміністратор зателефонує для узгодження візиту.':'У робочій версії напишемо повідомлення. Телефонувати не будемо.'}
document.querySelectorAll('input[name=channel]').forEach(i=>i.addEventListener('change',updateChannel));
function error(text,selector){q('#booking-error').textContent=text;q('#booking-error').hidden=false;if(selector)q(selector).focus();return false}
q('#booking-form').addEventListener('submit',e=>{e.preventDefault();if(step===0){if(pricing.details[q('#book-service').value]&&!q('#book-detail').value)return error('Оберіть конкретне дослідження або поверніться до допомоги з вибором.','#book-detail');step=1;renderBooking();q('#book-date').focus();return}if(step===1){const date=q('#book-date').value;if(!date||date<todayString())return error('Оберіть сьогоднішню або майбутню дату.','#book-date');const day=new Date(date+'T12:00:00').getDay();if(day===0)return error('У неділю клініка не працює. Оберіть інший день.','#book-date');if(day===6&&selectedTime>='14:00')return error('У суботу клініка працює до 14:00. Оберіть ранковий час.','.time-options button');step=2;renderBooking();q('#book-name').focus();return}if(q('#book-name').value.trim().length<2)return error('Вкажіть ваше ім’я — щонайменше 2 символи.','#book-name');const phone=q('#book-phone').value.replace(/\D/g,'');if(!/^(?:380\d{9}|0\d{9})$/.test(phone))return error('Вкажіть український номер: +380 та 9 цифр або 0 та 9 цифр.','#book-phone');const channel=q('input[name=channel]:checked').value;if(channel==='Telegram'&&!/^@?[a-zA-Z][a-zA-Z0-9_]{4,31}$/.test(q('#book-telegram').value.trim()))return error('Вкажіть Telegram username: від 5 символів, латинські літери, цифри або _.','#book-telegram');if(!q('#book-consent').checked)return error('Позначте згоду на використання контактів для узгодження візиту.','#book-consent');const quote=updatePrice();const detail=q('#book-detail-wrap').hidden?null:q('#book-detail').selectedOptions[0]?.textContent;const values=[['Послуга',q('#book-service').selectedOptions[0].textContent],...(detail&&q('#book-detail').value?[['Дослідження / процедура',detail]]:[]),...(q('#book-repeat').value==='repeat'?[['Тип прийому','Повторна консультація']]:[]),['Лікар',doctorLabel()],['Орієнтовно до оплати',quote.label],...(quote.note?[['Примітка',quote.note]]:[]),['Бажаний час',dateLabel()+', '+selectedTime],['Зв’язок',channel+(channel==='Дзвінок'?'':' · без дзвінка')],['Статус','Не надіслано (демонстрація)']];q('#booking-receipt').innerHTML=values.map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHTML(v)}</dd></div>`).join('');q('#booking-form').hidden=true;q('#booking-success').hidden=false;q('.booking-steps').hidden=true;q('#booking-title').hidden=true;q('.demo-note').hidden=true;q('#booking-dialog').scrollTop=0;q('#booking-success button').focus()});
q('#booking-dialog').addEventListener('close',()=>{q('#booking-form').reset();q('#booking-receipt').replaceChildren()});
// Optional browser tool: opens the same demonstration flow and never submits data.
if(window.BreorisLocale) window.BreorisLocale.translateTree();
if(!window.BreorisBooking && document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  const startTool={name:'start_demo_booking',title:'Відкрити демонстрацію запису',description:'Open the demonstration appointment form with an optional service. Does not book, send or save an appointment.',inputSchema:{type:'object',properties:{service:{type:'string',enum:bookServices}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(k=>k!=='service')||(input.service!==undefined&&!bookServices.includes(input.service)))throw new Error('Choose a service from the provided list.');openBooking(input.service);return{status:'demo_form_open',service:q('#book-service').value,appointmentCreated:false}}};
  try{Promise.resolve(document.modelContext.registerTool(startTool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

 document.addEventListener("change", event => { if(event.target.matches(".language-select")) document.querySelectorAll("#service-list [data-service]").forEach(item => { item.querySelector(".service-price").textContent = window.BreorisPricing.summary(item.dataset.service); }); });
